class Widget {
public:
  // Constructor for a pair of values
  Widget(int i, bool b) {}

  // Constructor for a list of strings
  Widget(std::initializer_list<std::string> il) {}
};

// uses braces, but types don't match std::initializer_list<std::string>
// The compiler falls back to normal overload resolution.
Widget w1{10, true}; // Calls Widget(int, bool)

// uses braces, and the types are compatible
Widget w2{"hello", "world"}; // Calls Widget(std::initializer_list<std::string>)
